// Official Python results only. Synthetic renderer fixture is generated by Python.
import {createRequire} from 'node:module';
import {existsSync,readFileSync,writeFileSync,mkdirSync} from 'node:fs';
import {spawn} from 'node:child_process';
import assert from 'node:assert/strict';
const require=createRequire(import.meta.url);
const {chromium}=require(process.env.PLAYWRIGHT_MODULE||'C:/Users/Admin/.cache/codex-runtimes/codex-primary-runtime/dependencies/node/node_modules/playwright');
const cases=JSON.parse(readFileSync('../../research/catalog-reasoner-mvp/cases/calibration.json','utf8')).cases;
const canonical=payload=>{const copy=structuredClone(payload);if(copy.answers.I10){copy.answers.I10.none??=false;copy.answers.I10.selected.sort((a,b)=>a.feature.localeCompare(b.feature));}return copy;};
const server=spawn(process.execPath,['server.mjs'],{env:{...process.env,PORT:'0'},windowsHide:true});let browser;
const report={official_pipeline:true,cases:[],checks:[],layout_findings:[],page_errors:[]};
try{
 const url=await new Promise((resolve,reject)=>{server.stdout.on('data',b=>{const m=String(b).match(/Local: (http:\/\/127\.0\.0\.1:\d+)/);if(m)resolve(m[1]);});server.on('error',reject);});
 const executablePath=['C:/Program Files/Google/Chrome/Application/chrome.exe','C:/Program Files (x86)/Microsoft/Edge/Application/msedge.exe'].find(existsSync);
 browser=await chromium.launch({headless:true,...(executablePath?{executablePath}:{})});
 const page=await browser.newPage();page.on('pageerror',e=>report.page_errors.push(e.message));
 const choose=async selector=>{const el=page.locator(selector);if(!await el.isChecked())await el.locator('..').click();};
 for(const index of [0,4,3]){
  const profile=cases[index];await page.goto(url+'/#form');await page.locator('#profile-form').waitFor();
  await page.evaluate(()=>{localStorage.clear();});await page.reload();await page.locator('#profile-form').waitFor();
  for(const [qid,value] of Object.entries(profile.form_answers.answers)){
   if(qid==='I10'){
    if(value.none)await choose('[name="I10-none"]');
    for(const item of value.selected){await choose(`[name="I10-feature"][value="${item.feature}"]`);await page.locator(`[name="I10-rank-${item.feature}"]`).selectOption(item.rank);}
   }else for(const selected of Array.isArray(value)?value:[value])await choose(`[name="${qid}"][value="${selected}"]`);
  }
  const responsePromise=page.waitForResponse(r=>r.url().endsWith('/api/run')&&r.request().method()==='POST');
  await page.getByRole('button',{name:'Xem kết quả đánh giá'}).click();
  const response=await responsePromise;assert.equal(response.status(),200);const result=await response.json();
  assert.deepEqual(response.request().postDataJSON(),canonical(profile.form_answers));
  await page.locator('[data-group="conditional"]').waitFor();
  for(const group of ['eligible','conditional','excluded']){
   assert.equal(await page.locator(`[data-group="${group}"] .catalog-row`).count(),result.groups[group].length);
   for(const candidate of result.groups[group]){
    const row=page.locator(`[data-candidate="${candidate.candidate_id}"]`);
    assert.ok(await row.locator('.reason-list li').count(),'Every candidate has readable reasons linked to requirements');
    if(candidate.score_interval)assert.ok((await row.locator('.score-interval').textContent()).includes(`[${candidate.score_interval.join(', ')}]`));
    await row.locator('summary').click();
    const shown=JSON.parse(await row.locator('pre').textContent());
    assert.deepEqual(shown.assessments,candidate.assessments);
    assert.deepEqual(shown.hard_conditions,candidate.hard_conditions);
    await row.locator('summary').click();
   }
  }
  if(!result.groups.eligible.length)assert.ok(await page.locator('#relaxations').count());
  assert.deepEqual(JSON.parse(await page.locator('#submitted-payload').textContent()),canonical(profile.form_answers));
  await page.setViewportSize({width:375,height:812});
  const widths=await page.evaluate(()=>({viewport:innerWidth,document:document.documentElement.scrollWidth}));
  if(widths.document>widths.viewport)report.layout_findings.push({case:profile.id,view:'report',...widths});
  await page.setViewportSize({width:1280,height:900});
  report.cases.push({id:profile.id,status:'passed',groups:Object.fromEntries(Object.entries(result.groups).map(([g,rs])=>[g,rs.length])),answer_ids_and_ranks_preserved:true,payload_note:'optional none is explicitly false; feature lists serialized in registry order',score_intervals_exact:true,trace_exact:true});
 }
 await page.goto(url+'/#form');await page.locator('#profile-form').waitFor();
 await page.evaluate(()=>localStorage.clear());await page.reload();await page.locator('#profile-form').waitFor();
 await choose('[name="I09"][value="none"]');await choose('[name="I09"][value="databricks"]');
 await page.getByRole('button',{name:'Xem kết quả đánh giá'}).click();assert.ok((await page.locator('#form-errors').textContent()).includes('answers.I09'));
 await page.locator('[name="I09"][value="databricks"]').locator('..').click();
 await choose('[name="I10-feature"][value="branching"]');
 await page.getByRole('button',{name:'Xem kết quả đánh giá'}).click();assert.ok((await page.locator('#form-errors').textContent()).includes('rank'));
 report.checks.push('none exclusivity and missing rank show field and correction');
 await page.setViewportSize({width:375,height:812});
 let width=await page.evaluate(()=>({viewport:innerWidth,document:document.documentElement.scrollWidth}));
 if(width.document>width.viewport)report.layout_findings.push({view:'form',...width});
 await page.locator('[name="I01"][value="aws"]').scrollIntoViewIfNeeded();await page.locator('[name="I01"][value="aws"]').focus();await page.keyboard.press('ArrowDown');
 assert.ok(await page.locator('[name="I01"][value="azure"]').isChecked());
 const focus=await page.evaluate(()=>({tag:document.activeElement.tagName,outline:getComputedStyle(document.activeElement).outlineStyle,outlineWidth:getComputedStyle(document.activeElement).outlineWidth,rect:document.activeElement.getBoundingClientRect().toJSON()}));
 report.focus_measurement=focus;
 if(focus.outline==='none'||focus.rect.width===0||focus.rect.height===0)report.layout_findings.push({view:'form',problem:'focused native control has no visible area or outline',focus});
 report.checks.push('radio arrow-key navigation changes the selected answer');
 const syntheticPath='../../research/catalog-reasoner-mvp/outputs/synthetic-ui-three-groups.json';
 if(existsSync(syntheticPath)){
  const fixture=JSON.parse(readFileSync(syntheticPath,'utf8'));
  await page.evaluate(value=>window.dispatchEvent(new CustomEvent('catalog-backend-result',{detail:value})),fixture);
  for(const group of ['eligible','conditional','excluded'])assert.equal(await page.locator(`[data-group="${group}"] .catalog-row`).count(),1);
  assert.ok((await page.locator('main').textContent()).includes('DỮ LIỆU TỔNG HỢP'));
  report.checks.push('three populated UI groups match a clearly named synthetic result from official Python');
 }
 assert.deepEqual(report.page_errors,[]);
 report.status=report.layout_findings.length?'functional_pass_with_layout_findings':'passed';
 mkdirSync('artifacts',{recursive:true});writeFileSync('artifacts/e2e-mvp.json',JSON.stringify(report,null,2)+'\n');
 await page.screenshot({path:'artifacts/e2e-mvp-mobile.png',fullPage:true});
 console.log(JSON.stringify(report,null,2));
 assert.equal(report.layout_findings.length,0,'No horizontal overflow or hidden keyboard focus is allowed');
}finally{if(browser)await browser.close();server.kill();}
